import os
import hashlib
import time
import json
import tempfile
import threading
from http.server import HTTPServer, BaseHTTPRequestHandler
from urllib.parse import urlparse, parse_qs
import hmac
import secrets

SESSION_DIR = os.environ.get('SESSION_DIR', '/tmp/sessions')
SECRET_KEY = os.environ.get('SECRET_KEY', secrets.token_hex(32))
UPLOAD_DIR = os.environ.get('UPLOAD_DIR', '/tmp/uploads')

def ensure_dirs():
    os.makedirs(SESSION_DIR, mode=0o700, exist_ok=True)
    os.makedirs(UPLOAD_DIR, mode=0o700, exist_ok=True)

def generate_session_id():
    return secrets.token_hex(16)

def sign_data(data: bytes) -> str:
    return hmac.new(SECRET_KEY.encode(), data, hashlib.sha256).hexdigest()

class SessionStore:
    """File-based session store with path traversal protection."""

    def __init__(self, base_dir: str):
        self._base_dir = os.path.realpath(base_dir)
        self._lock = threading.Lock()

    def _safe_path(self, session_id: str) -> str:
        """Validate session_id and return safe file path.
        Prevents path traversal by checking the resolved path."""
        # Only allow alphanumeric session IDs
        if not session_id.replace('-', '').replace('_', '').isalnum():
            raise ValueError("Invalid session ID format")

        candidate = os.path.join(self._base_dir, session_id + '.json')
        resolved = os.path.realpath(candidate)

        # Ensure resolved path is within base directory
        if not resolved.startswith(self._base_dir + os.sep):
            raise ValueError("Path traversal detected")

        return resolved

    def read_session(self, session_id: str) -> dict:
        """Read session data from file."""
        path = self._safe_path(session_id)

        if not os.path.exists(path):
            return {}

        with open(path, 'r') as f:
            return json.load(f)

    def write_session(self, session_id: str, data: dict) -> None:
        """Write session data to file atomically."""
        path = self._safe_path(session_id)

        tmp_fd, tmp_path = tempfile.mkstemp(dir=self._base_dir, suffix='.tmp')
        try:
            with os.fdopen(tmp_fd, 'w') as f:
                json.dump(data, f)
            os.rename(tmp_path, path)
        except Exception:
            os.unlink(tmp_path)
            raise

    def delete_session(self, session_id: str) -> None:
        """Delete session file."""
        path = self._safe_path(session_id)
        if os.path.exists(path):
            os.unlink(path)


class FileManager:
    """Manages user file uploads with access control."""

    def __init__(self, base_dir: str):
        self._base_dir = os.path.realpath(base_dir)

    def _validate_path(self, username: str, filename: str) -> str:
        """Validate that the requested file is within the user's directory.
        Uses realpath to resolve symlinks and prevent traversal."""
        if not username.isalnum():
            raise ValueError("Invalid username")

        # Sanitize filename - remove any path separators
        safe_filename = os.path.basename(filename)
        if not safe_filename or safe_filename.startswith('.'):
            raise ValueError("Invalid filename")

        user_dir = os.path.join(self._base_dir, username)
        os.makedirs(user_dir, mode=0o700, exist_ok=True)

        target_path = os.path.join(user_dir, safe_filename)

        # Security check: resolve symlinks and verify path is within user_dir
        resolved_target = os.path.realpath(target_path)
        resolved_user_dir = os.path.realpath(user_dir)

        if not resolved_target.startswith(resolved_user_dir + os.sep):
            raise ValueError("Access denied: path traversal attempt")

        return target_path  # Return original path, not resolved

    def read_file(self, username: str, filename: str) -> bytes:
        """Read a file from user's upload directory."""
        validated_path = self._validate_path(username, filename)

        # Second existence check after validation
        if not os.path.isfile(validated_path):
            raise FileNotFoundError("File not found")

        with open(validated_path, 'rb') as f:
            return f.read()

    def write_file(self, username: str, filename: str, data: bytes) -> None:
        """Write a file to user's upload directory."""
        validated_path = self._validate_path(username, filename)

        with open(validated_path, 'wb') as f:
            f.write(data)

    def list_files(self, username: str) -> list:
        """List files in user's directory."""
        if not username.isalnum():
            raise ValueError("Invalid username")
        user_dir = os.path.join(self._base_dir, username)
        if not os.path.isdir(user_dir):
            return []
        return [f for f in os.listdir(user_dir) if not f.startswith('.')]


class RequestHandler(BaseHTTPRequestHandler):
    session_store = SessionStore(SESSION_DIR)
    file_manager = FileManager(UPLOAD_DIR)

    def _get_session(self) -> tuple:
        cookie = self.headers.get('Cookie', '')
        session_id = None
        for part in cookie.split(';'):
            part = part.strip()
            if part.startswith('sid='):
                session_id = part[4:]
                break

        if session_id:
            data = self.session_store.read_session(session_id)
            if data:
                return session_id, data

        return None, {}

    def _authenticate(self, session_data: dict) -> str:
        """Return username if authenticated, None otherwise."""
        username = session_data.get('username')
        if username and session_data.get('authenticated'):
            # Check session expiry
            expires = session_data.get('expires', 0)
            if time.time() < expires:
                return username
        return None

    def do_GET(self):
        parsed = urlparse(self.path)
        params = parse_qs(parsed.query)

        if parsed.path == '/files':
            session_id, session_data = self._get_session()
            username = self._authenticate(session_data)
            if not username:
                self.send_response(401)
                self.end_headers()
                return

            filename = params.get('name', [None])[0]
            if filename:
                try:
                    content = self.file_manager.read_file(username, filename)
                    self.send_response(200)
                    self.send_header('Content-Type', 'application/octet-stream')
                    self.end_headers()
                    self.wfile.write(content)
                except (ValueError, FileNotFoundError) as e:
                    self.send_response(403)
                    self.end_headers()
            else:
                files = self.file_manager.list_files(username)
                self.send_response(200)
                self.send_header('Content-Type', 'application/json')
                self.end_headers()
                self.wfile.write(json.dumps(files).encode())
        else:
            self.send_response(404)
            self.end_headers()

    def log_message(self, format, *args):
        pass  # Suppress default logging


def main():
    ensure_dirs()
    server = HTTPServer(('127.0.0.1', 8080), RequestHandler)
    print("Server running on 127.0.0.1:8080")
    server.serve_forever()

if __name__ == '__main__':
    main()
